  if (row.isCheckinOnly) return `<td style="padding:4px 8px;border:1px solid #ddd;text-align:center;" colspan="1"><span style="background:#BFDBFE;color:#1E40AF;font-size:11px;font-weight:700;padding:3px 10px;border-radius:12px">🔑 Άφιξη ${row.nextNights?'('+row.nextNights+' νύχτες)':''}</span></td>`;
