  </td>`;
}

function _opsCheckoutDateCell(row, i) {
  if (row.isCheckinOnly) {
    return `<td style="padding:4px 6px;border:1px solid #ddd;text-align:center;color:#9CA3AF;font-size:12px">—</td>`;
  }
  if (row.alreadyCleaned) {
    const lbl = 'ήδη καθαρό ' + (row.cleanedDate ? _opsFmtDate(row.cleanedDate) : '');
    return `<td style="padding:4px 6px;border:1px solid #ddd;text-align:center">
