        style="background:#FEF08A;color:#713F12;padding:4px 6px;border-radius:4px;cursor:pointer;font-size:11px;font-weight:600;white-space:nowrap">
        ${lbl}
      </div>
    </td>`;
  }
  return `<td style="padding:4px 6px;border:1px solid #ddd;text-align:center">
